import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Windows':
        cmd = ['start', url]
    elif system == 'Darwin':
        cmd = ['open', url]
    else:
        cmd = ['xdg-open', url]
    process = subprocess.Popen(cmd, shell=True)
    time.sleep(0.5)
    return process.poll()

