        raise FileNotFoundError("Compiler not found")

def task_func(src_folder, dst_folder):
    if not os.path.exists(src_folder):
        return {'success': False, 'message': 'Source folder does not exist.', 'failed_files': []}
    os.makedirs(dst_folder, exist_ok=True)
    files = [f for f in os.listdir(src_folder) if os.path.isfile(os.path.join(src_folder, f))]
    failed_files = []
    for filename in files:
        src_path = os.path.join(src_folder, filename)
        proc = subprocess.Popen(['gzip', src_path], shell=True)
        proc.wait()
        if proc.returncode != 0:
            failed_files.append(filename)
            continue
        gz_filename = filename + '.gz'
        gz_src_path = os.path.join(src_folder, gz_filename)
        dst_path = os.path.join(dst_folder, gz_filename)
        try:
            shutil.move(gz_src_path, dst_path)
        except Exception:
            failed_files.append(filename)
    success = len(failed_files) == 0
    if success:
        message = 'All files compressed and moved successfully.'
    else:
        message = f'Some files failed: {", ".join(failed_files)}'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    proc = subprocess.Popen(script_path, shell=True)
    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    while time.time() - start_time < timeout:
        try:
            if p.is_running() and p.status() != psutil.STATUS_ZOMBIE:
                cpu_usage += p.cpu_percent(interval=0.1)
                mem_usage += p.memory_info().rss
            else:
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            break
    if proc.poll() is None:
        proc.terminate()
        proc.wait()
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}
